  "answer": {
    "claims": [
      {
        "statement": "Alphabet discloses that its capital investments in property and equipment consist primarily of two major categories: (1) technical infrastructure, which consists of investments in servers and network equipment, data center land, and building construction and improvements; and (2) office facilities, ground-up development projects, and building improvements.",
        "temporal_basis": "not_period_specific",
        "period_context": "Alphabet FY2025 10-K, Capital Expenditures and Leases / Capital Expenditures disclosure, page 38; the category disclosure is not tied to a single fiscal year in the read block.",
        "citations": [
          {
            "context_id": "ev-88d6156db193f765774ee294",
            "block_id": "block-000614-4e902c64",
            "quote": "Our capital investments in property and equipment consist primarily of the following major categories:",
            "label": "Capital expenditures categories introduction"
          },
          {
            "context_id": "ev-88d6156db193f765774ee294",
            "block_id": "block-000615-414413ff",
            "quote": "•technical infrastructure, which consists of our investments in servers and network equipment, data center land, and building construction and improvements; and",
            "label": "Capital expenditures category 1"
          },
          {
            "context_id": "ev-88d6156db193f765774ee294",
            "block_id": "block-000616-051391dc",
            "quote": "•office facilities, ground-up development projects, and building improvements.",
            "label": "Capital expenditures category 2"
          }
        ]
      },
      {
        "statement": "For the years ended December 31, 2024 and 2025, Alphabet reported capital expenditures of $52.5 billion and $91.4 billion, respectively.",
        "temporal_basis": "reported_actual",
        "period_context": "Years ended December 31, 2024 and December 31, 2025, Alphabet FY2025 10-K, page 38.",
        "citations": [
          {
            "context_id": "ev-88d6156db193f765774ee294",
            "block_id": "block-000618-45e1aa4d",
            "quote": "During the years ended December 31, 2024 and 2025, we spent $52.5 billion and $91.4 billion on capital expenditures, respectively.",
            "label": "Reported capital expenditures amounts"
          }
        ]
      },
      {
        "statement": "Alphabet discloses that in 2026 it expects to significantly increase, relative to 2025, its investment in technical infrastructure, including servers and network equipment, and data centers.",
        "temporal_basis": "forward_looking",
        "period_context": "Forward-looking statement for 2026 relative to 2025, Alphabet FY2025 10-K, page 38.",
        "citations": [
          {
            "context_id": "ev-88d6156db193f765774ee294",
            "block_id": "block-000618-45e1aa4d",
            "quote": "In 2026, we expect to significantly increase, relative to 2025, our investment in our technical infrastructure, including servers and network equipment, and data centers.",
            "label": "Forward-looking capital expenditure expectation"
          }
        ]
      }
    ],
    "model_claimed_coverage": "claimed_complete",
    "coverage_note": "Read the Capital Expenditures and Leases / Capital Expenditures section on page 38, including the introduction and the complete two-item category list, plus the following paragraph containing reported 2024/2025 capital expenditure amounts and the 2026 forward-looking statement. This covers the requested capital-expenditure major-use disclosure categories without inferring maintenance capex or AI investment returns.",
    "unresolved_questions": []
  }
}
